```yaml
name: Community PR Permissions Check

on:
  pull_request:
    types: [opened, synchronize, reopened]

jobs:
  check-permissions:
    runs-on: ubuntu-latest
    steps:
      - name: Checkout repository
        uses: actions/checkout@v4

      - name: Verify PR author membership
        uses: actions/github-script@v6
        with:
          script: |
            const pr = context.payload.pull_request;
            const username = pr.user.login;
            const isFork = pr.head.repo.fork;
            if (isFork) {
              try {
                const { data: membership } = await github.orgs.getMembershipForUser({
                  org: context.repo.owner,
                  username: username
                });
                if (!membership || membership.role === 'outside') {
                  core.setFailed(
                    `Community PR author @${username} is not a member of the ${context.repo.owner} organization. ` +
                    `Please ensure you have the appropriate permissions or contact a maintainer.`
                  );
                }
              } catch (error) {
                core.setFailed(`Failed to check membership for @${username}: ${error.message}`);
              }
            } else {
              core.info('PR is from the same repository, skipping membership check.');
            }

      - name: Ensure community PR has "community" label
        uses: actions/github-script@v6
        with:
          script: |
            const pr = context.payload.pull_request;
            const labels = pr.labels.map(l => l.name);
            if (!labels.includes('community')) {
              core.setFailed('Community PRs must have the "community" label.');
            }
```

